import{_ as o,a as s,o as n,a2 as e}from"./chunks/framework.DCcmcJcL.js";const d=JSON.parse('{"title":"About","description":"","frontmatter":{},"headers":[],"relativePath":"configure/about.md","filePath":"configure/about.md","lastUpdated":1789441803000}'),r={name:"configure/about.md"};function a(g,t,i,h,l,u){return n(),s("div",null,t[0]||(t[0]=[e('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h1><p>The <strong>About</strong> screen shows what your store runs on and which services it uses. There is nothing to change here, so the screen has no <strong>Save Configuration</strong> button. Open it when support asks which version you are on, or to confirm that a setting made elsewhere has taken effect.</p><p>Go to <strong>Configure &gt;&gt; About &gt;&gt; General</strong>. The information is grouped into cards in two columns.</p><p>The first column holds these cards:</p><ul><li><strong>Bagisto</strong> – the <strong>Version</strong> of Bagisto your store runs.</li><li><strong>Database</strong> – the database <strong>Engine</strong> and its <strong>Version</strong>.</li><li><strong>Search</strong> – the search <strong>Engine</strong> in use, as set under <a href="./search-engines.html">Search Engines</a>. For Elasticsearch it also shows the <strong>Version</strong> and a <strong>Status</strong> with a green or red dot, as found by a <strong>Test Connection</strong> in the last five minutes. Otherwise <strong>Version</strong> shows <strong>Not Available</strong> and <strong>Status</strong> shows <strong>Not Checked</strong>.</li><li><strong>Mail</strong> – the <strong>Transport</strong> email is sent through, such as <strong>SMTP</strong> or <strong>Brevo API</strong>, as set under <a href="./email-settings.html">Email Settings</a>.</li><li><strong>Storage</strong> – whether the <strong>Public Link</strong> to uploaded files exists, and the storage <strong>Driver</strong>, as set under <a href="./file-management.html">File Management</a>. For Amazon S3 or Cloudflare R2 it also shows a <strong>Status</strong> with a green or red dot.</li><li><strong>Cached</strong> – whether the <strong>Configuration</strong>, <strong>Events</strong>, <strong>Routes</strong> and <strong>Views</strong> are cached. Clear or build them under <a href="./cache-management.html">Cache Management</a>.</li></ul><p>The second column holds these cards:</p><ul><li><strong>Environment</strong> – the <strong>Application Name</strong>, the <strong>Laravel Version</strong>, <strong>PHP Version</strong> and <strong>Composer Version</strong>, the <strong>Environment</strong> (<strong>Local</strong>, <strong>Staging</strong>, <strong>Testing</strong> or <strong>Production</strong>), whether <strong>Debug Mode</strong> is on, the store <strong>URL</strong>, whether <strong>Maintenance Mode</strong> is on, the <strong>Timezone</strong> and the <strong>Locale</strong>.</li><li><strong>Drivers</strong> – the services that handle the <strong>Cache</strong>, the <strong>Log</strong>, the <strong>Queue</strong> and the <strong>Session</strong>.</li></ul><p>A value that isn&#39;t set up shows <strong>Not Configured</strong>.</p><p>If this screen shows <strong>Debug Mode</strong> on while the environment is <strong>Production</strong>, ask whoever manages the server to turn debug mode off, because it can show technical details to visitors when something goes wrong.</p><h2 id="differences-in-bagisto-2-4" tabindex="-1">Differences in Bagisto 2.4 <a class="header-anchor" href="#differences-in-bagisto-2-4" aria-label="Permalink to &quot;Differences in Bagisto 2.4&quot;">​</a></h2><p>Bagisto 2.4 has no <strong>About</strong> screen.</p>',11)]))}const f=o(r,[["render",a]]);export{d as __pageData,f as default};
